do $$declare student uuid:='00000005-0000-4000-8000-000000000000'; other_student uuid:='00000009-0000-4000-8000-000000000000';
  version uuid; target uuid; program uuid; source_course uuid; target_course uuid; term uuid; result jsonb; transfer jsonb; before_org jsonb; count_before bigint;
begin
  perform test.login(1);
  select (value->>'id')::uuid into version from test.records where name='version';
  select (value->>'id')::uuid into target from test.records where name='target_version';
  select (value->>'id')::uuid into program from test.records where name='program';
  select (value->>'id')::uuid into source_course from test.records where name='source_course';
  select (value->>'id')::uuid into target_course from test.records where name='course';
  select (value->>'id')::uuid into term from test.records where name='term';
  perform test.call('updateCurriculumVersion',jsonb_build_object('id',target),'{"status":"active"}');
  perform test.call('createCurriculumTermCourse','{}',jsonb_build_object('curriculum_term_id',term,'course_id',source_course,'is_elective_slot',false,'nominal_units',3));
  perform test.call('createCurriculumPairEquivalence','{}',jsonb_build_object('from_curriculum_version_id',version,'to_curriculum_version_id',target,'source_course_id',source_course,'target_course_id',target_course));
  perform test.login(4);
  before_org:=saais_private.organization(student);
  select count(*) into count_before from public.audit_log_entry;
  result:=test.call('previewCurriculumShift',jsonb_build_object('student_id',student),jsonb_build_object('curriculum_version_id',target));
  perform test.assert(result='{"carried_units":3,"lost_units":0,"projected_gwa":2,"mutates_records":false}'::jsonb,'pair preview calculation');
  perform test.assert((select count(*)=count_before from public.audit_log_entry),'preview wrote audit');
  perform test.assert(saais_private.organization(student)=before_org,'preview changed assignment');
  transfer:=test.call('endorseCurriculumTransfer',jsonb_build_object('student_id',student),jsonb_build_object('to_curriculum_version_id',target,'endorsement_note','Test endorsement'));
  perform test.expect('PT409','endorseCurriculumTransfer',jsonb_build_object('student_id',student),jsonb_build_object('to_curriculum_version_id',target,'endorsement_note','Duplicate pending'));
  perform test.login(6);
  perform test.expect('PT403','decideCurriculumTransfer',jsonb_build_object('transfer_id',transfer->>'id'),'{"decision":"approved"}');
  perform test.login(2);
  perform test.expect('PT400','decideCurriculumTransfer',jsonb_build_object('transfer_id',transfer->>'id'),'{"decision":"rejected"}');
  result:=test.call('decideCurriculumTransfer',jsonb_build_object('transfer_id',transfer->>'id'),'{"decision":"rejected","decision_note":"Test rejection"}');
  perform test.assert(saais_private.organization(student)=before_org,'rejection changed assignment');
  perform test.expect('PT409','decideCurriculumTransfer',jsonb_build_object('transfer_id',transfer->>'id'),'{"decision":"approved"}');
  perform test.login(4);
  transfer:=test.call('endorseCurriculumTransfer',jsonb_build_object('student_id',student),jsonb_build_object('to_curriculum_version_id',target,'endorsement_note','Second endorsement'));
  perform test.login(2);
  result:=test.call('decideCurriculumTransfer',jsonb_build_object('transfer_id',transfer->>'id'),'{"decision":"approved"}');
  perform test.assert((saais_private.organization(student)->>'curriculum_version_id')::uuid=target,'approval did not assign target');
  perform test.assert(saais_private.organization(student)->>'adviser_id'=before_org->>'adviser_id','transfer changed adviser');
  perform test.assert((select count(*)=1 from public.equivalency_decision where student_id=student and revoked_at is null),'pair rules not applied');
  perform test.assert(exists(select 1 from public.student_curriculum_assignment old_a join public.student_curriculum_assignment new_a on new_a.student_id=old_a.student_id and new_a.start_date=old_a.end_date where old_a.student_id=student and old_a.curriculum_version_id=version and new_a.curriculum_version_id=target),'assignment continuity');
  perform test.expect('PT403','assignStudentCurriculum',jsonb_build_object('student_id',other_student),jsonb_build_object('curriculum_version_id',version,'program_id',program,'start_date','2026-02-01','reason','Out of scope'));
  perform test.login(1);
  perform test.expect('PT400','assignStudentCurriculum',jsonb_build_object('student_id',other_student),jsonb_build_object('curriculum_version_id',version,'program_id',(select value->>'id' from test.records where name='program_b'),'start_date','2026-02-01','reason','Mismatched program'));
  result:=test.call('assignStudentCurriculum',jsonb_build_object('student_id',other_student),jsonb_build_object('curriculum_version_id',version,'program_id',program,'start_date','2026-02-01','reason','Test direct assignment'));
  perform test.assert((result->>'curriculum_version_id')::uuid=version,'direct assignment failed');
end$$;
